package dev.utherhel.attributification.selftest;

import java.lang.reflect.Method;
import java.util.Optional;

/**
 * Loader-neutral facts for the self-test, by reflection only (no loader API on the compile classpath, so the same
 * file serves Fabric, Forge and NeoForge). Generated by dev/modtest/sync.py; edit the template.
 */
public final class ModTestHook {
    private ModTestHook() {
    }

    /**
     * -Dmodtest.audit=1: forces every mixin target of this side to load now (MixinEnvironment.audit), so a mixin that
     * cannot apply shows up in this run instead of at the class's first use, or never on a path no scene reaches.
     */
    public static String audit() {
        if (!"1".equals(System.getProperty("modtest.audit"))) return "skipped (modtest.audit not set)";
        try {
            Class<?> env = Class.forName("org.spongepowered.asm.mixin.MixinEnvironment");
            Object current = env.getMethod("getCurrentEnvironment").invoke(null);
            env.getMethod("audit").invoke(current);
            return null;
        } catch (ReflectiveOperationException | LinkageError e) {
            Throwable cause = e.getCause() != null ? e.getCause() : e;
            return "audit failed: " + Report.describe(cause);
        }
    }

    public static String loader() {
        if (present("net.fabricmc.loader.api.FabricLoader")) return present("org.quiltmc.loader.api.QuiltLoader") ? "quilt" : "fabric";
        if (present("net.neoforged.fml.ModList")) return "neoforge";
        if (present("net.minecraftforge.fml.ModList")) return "forge";
        return "unknown";
    }

    public static boolean isLoaded(String id) {
        try {
            if (loader().equals("fabric") || loader().equals("quilt")) {
                Object fl = Class.forName("net.fabricmc.loader.api.FabricLoader").getMethod("getInstance").invoke(null);
                return (boolean) fl.getClass().getMethod("isModLoaded", String.class).invoke(fl, id);
            }
            Object list = modList();
            return list != null && (boolean) list.getClass().getMethod("isLoaded", String.class).invoke(list, id);
        } catch (ReflectiveOperationException | LinkageError e) {
            return false;
        }
    }

    public static String version(String id) {
        try {
            if (loader().equals("fabric") || loader().equals("quilt")) {
                Object fl = Class.forName("net.fabricmc.loader.api.FabricLoader").getMethod("getInstance").invoke(null);
                Optional<?> c = (Optional<?>) fl.getClass().getMethod("getModContainer", String.class).invoke(fl, id);
                if (c.isEmpty()) return "";
                Object meta = call(c.get(), "getMetadata");
                return String.valueOf(call(call(meta, "getVersion"), "getFriendlyString"));
            }
            Object list = modList();
            if (list == null) return "";
            Optional<?> c = (Optional<?>) list.getClass().getMethod("getModContainerById", String.class).invoke(list, id);
            return c.isEmpty() ? "" : String.valueOf(call(call(c.get(), "getModInfo"), "getVersion"));
        } catch (ReflectiveOperationException | LinkageError e) {
            return "";
        }
    }

    private static Object modList() throws ReflectiveOperationException {
        String cls = loader().equals("neoforge") ? "net.neoforged.fml.ModList" : "net.minecraftforge.fml.ModList";
        return Class.forName(cls).getMethod("get").invoke(null);
    }

    private static Object call(Object o, String name) throws ReflectiveOperationException {
        Method m = o.getClass().getMethod(name);
        m.setAccessible(true);
        return m.invoke(o);
    }

    private static boolean present(String cls) {
        try {
            Class.forName(cls, false, ModTestHook.class.getClassLoader());
            return true;
        } catch (ClassNotFoundException | LinkageError e) {
            return false;
        }
    }
}
